{
  "packet_id": "H6-T04-2",
  "claim_id": "C021",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C021.main",
    "value": "Accounts whose publication opportunity has not yet occurred should be reported separately.",
    "scope": "Reporting treatment of accounts still awaiting their publication opportunity.",
    "provenance": {
      "refs": [
        {
          "source_id": "P011",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly specifies separate reporting for these accounts."
    }
  },
  "signal_basis": {
    "component_id": "C021.signal_basis",
    "value": "Follow-up identifies accounts whose publication opportunity has not yet occurred; these accounts cannot yet establish failure to publish, and intended roster dates may change.",
    "scope": "Accounts followed through the agreed observation window, with publication opportunity assessed against intended roster timing.",
    "provenance": {
      "refs": [
        {
          "source_id": "P011",
          "role": "SUPPORT"
        },
        {
          "source_id": "P024",
          "role": "SUPPORT"
        },
        {
          "source_id": "P009",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P011 supplies the follow-up and account category; P024 supplies its interpretive limitation and timing uncertainty. P009 defines the observation-window context."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C021.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The reporting claim is supported without an unresolved empirical relation."
    }
  },
  "rationale": "Given identification of accounts still awaiting their publication opportunity, separate reporting preserves the distinction between an opportunity that has not occurred and failure to publish. This licenses the stated reporting treatment within its narrow scope.",
  "uncertainty": "Intended roster dates may change, so the awaiting-opportunity classification remains time-dependent.",
  "anomalies": []
}
